html:
{%- from "iso_compliance/templates/includes/controlled_document_macros.html" import
	control_header, watermark, authority_block, change_history, body, title_block with context -%}

<style>
	/*
	 * The chrome header/footer template sizes its page to the measured height of
	 * the header, then adds 1mm of body padding and 1mm above and below the
	 * wrapper *inside* that page. Content therefore exceeds the page it was
	 * measured for, and because a table row cannot split it moves wholesale to a
	 * second sheet -- which is never merged, so the control block disappears from
	 * the printed document with no error anywhere. Reclaiming the padding is what
	 * makes the repeated header reliable.
	 */
	body { padding: 0 !important; margin: 0 !important; }
	.cd-headband { height: 38px; overflow: hidden; }
	.print-format .wrapper { padding: 0 !important; margin: 0 !important; }

	.print-format { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 9.5pt; color: #111; }

	/* ---- controlled header, repeated on every page ---- */
	table.cd-header { width: 100%; border-collapse: collapse; table-layout: fixed; }
	table.cd-header td, table.cd-header th {
		border: 0.6pt solid #000; padding: 2.4pt 4pt; font-size: 7.6pt; vertical-align: middle;
	}
	/* Every cell is capped. A CSS table row grows to fit its content, so pinning the
	   td height alone is not enough: one long title was still enough to push the row
	   past the header page and drop the control block from the whole document. */
	.cd-lbl { text-transform: uppercase; letter-spacing: 0.2pt; font-size: 5.6pt;
		color: #555; font-weight: 600; line-height: 1.1; margin-bottom: 1pt;
		height: 7px; overflow: hidden; }
	.cd-val { font-size: 8pt; font-weight: 700; line-height: 1.15;
		max-height: 19px; overflow: hidden; }
	/* The repeated header is rendered into a page sized to its measured height, and
	   only that page's first sheet is merged onto the body. A value tall enough to
	   push the single row past that height moves the whole row to a second sheet,
	   which is then never merged -- the control block silently disappears. Clamping
	   the two free-text cells keeps the row height bounded whatever the content. */
	.cd-c-title .cd-val { font-size: 7.2pt; display: -webkit-box; -webkit-line-clamp: 2;
		-webkit-box-orient: vertical; overflow: hidden; }
	.cd-org-name { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
		overflow: hidden; }
	table.cd-header td { overflow: hidden; }
	.cd-org { width: 22%; }
	/* Kept small on purpose. The repeated header is rendered into a page sized to
	   its measured height and only that page's first sheet is merged onto the body,
	   so anything that grows this row silently drops the whole control block. */
	.cd-org-name { font-size: 7.4pt; font-weight: 700; line-height: 1.1; height: 9px; overflow: hidden; }
	/* A fixed row height makes the measured header and the laid-out header agree
	   whatever the content or image timing. */
	table.cd-header td, table.cd-header th { height: 30px; overflow: hidden; }
	.cd-org-addr { font-size: 5pt; color: #555; line-height: 1.05;
		display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

	/* ---- title block, page one only ---- */
	table.cd-title { width: 100%; border-collapse: collapse; margin: 0 0 13pt;
		border-bottom: 1.6pt solid #1f3d2b; }
	table.cd-title td { padding: 0 0 6pt; vertical-align: bottom; }
	.cd-wordmark { height: 34px; width: auto; display: block; }
	.cd-title-meta { text-align: right; }
	.cd-title-kicker { font-size: 6.6pt; text-transform: uppercase; letter-spacing: 1.1pt;
		color: #6a6a6a; font-weight: 600; }
	.cd-title-num { font-size: 11pt; font-weight: 800; letter-spacing: 0.2pt; color: #1f3d2b; }
	.cd-title-main { padding-top: 4pt !important; }
	h1.cd-doc-title { font-size: 17pt; line-height: 1.2; font-weight: 800; margin: 0 0 3pt;
		color: #111; letter-spacing: -0.2pt; }
	.cd-title-sub { font-size: 7.6pt; color: #555; }
	.cd-strong { font-weight: 700; }
	.cd-nowrap { white-space: nowrap; }
	.cd-c-num { width: 21%; }
	.cd-c-title { width: 23%; }
	.cd-c-ctl { width: 13%; }
	.cd-c-st { width: 9%; }
	.cd-c-num .cd-val { font-size: 7.2pt; }
	.cd-c-ctl .cd-val, .cd-c-st .cd-val { font-size: 7.2pt; }
	.cd-sub { display: block; font-weight: 400; font-size: 6pt; color: #555; margin-top: 1pt; }

	/* ---- footer ---- */
	table.cd-footer { width: 100%; border-top: 0.6pt solid #000; border-collapse: collapse;
		padding-top: 3pt; font-size: 6.4pt; color: #333; line-height: 1.3; }
	table.cd-footer td { padding: 3pt 2pt 0; vertical-align: top; }
	.cd-notice { text-transform: uppercase; letter-spacing: 0.2pt; }
	.cd-pageno { width: 30%; text-align: right; white-space: nowrap; font-weight: 700;
		font-size: 6.6pt; color: #111; }

	/* ---- body ---- */
	.cd-section { margin: 0 0 11pt; }
	.cd-h2 { font-size: 10.5pt; font-weight: 700; margin: 0 0 4pt;
		border-bottom: 0.8pt solid #333; padding-bottom: 2pt; }
	.cd-h3 { font-size: 9.5pt; font-weight: 700; margin: 7pt 0 2pt; }
	.cd-rich { line-height: 1.45; text-align: justify; }
	.cd-rich p { margin: 0 0 5pt; }
	.cd-list { margin: 0; padding-left: 16pt; line-height: 1.45; }
	.cd-step { margin-bottom: 6pt; }

	table.cd-table { width: 100%; border-collapse: collapse; margin-top: 3pt; }
	table.cd-table td, table.cd-table th { border: 0.5pt solid #666; padding: 3pt 4.5pt;
		font-size: 8.2pt; vertical-align: top; text-align: left; }
	table.cd-table th { background: #f2f2f2; font-weight: 600; }
	table.cd-history td, table.cd-history th { font-size: 7pt; padding: 2.5pt 3pt; }
	.cd-history .cd-desc { width: 24%; }
	.cd-empty { color: #777; font-style: italic; }
	.cd-source { font-size: 8pt; color: #444; margin: 0 0 5pt; }
	table.cd-register td, table.cd-register th { font-size: 7pt; padding: 2.5pt 3.5pt; }

	/* ---- authority ---- */
	table.cd-authority { width: 100%; border-collapse: collapse; margin-top: 14pt; }
	table.cd-authority td, table.cd-authority th { border: 0.6pt solid #000; padding: 5pt 6pt;
		font-size: 8pt; text-align: center; width: 33.33%; }
	table.cd-authority th { background: #ececec; text-transform: uppercase; font-size: 6.8pt;
		letter-spacing: 0.3pt; }
	.cd-sig-name { font-weight: 700; min-height: 22pt; padding-top: 12pt; }
	.cd-sig-date { font-size: 6.6pt; color: #555; }
	.cd-authority-note { font-size: 6.4pt; color: #666; margin-top: 3pt; font-style: italic; }

	/* ---- watermark ---- */
	.cd-watermark { position: fixed; top: 44%; left: 0; width: 100%; text-align: center;
		transform: rotate(-24deg); font-weight: 800; letter-spacing: 3pt;
		pointer-events: none; z-index: 0; text-transform: uppercase; }
	.cd-watermark-draft { font-size: 64pt; color: #c02828; opacity: 0.08; }
	.cd-watermark-obsolete { font-size: 56pt; color: #777777; opacity: 0.10; }
	.cd-watermark-uncontrolled { font-size: 22pt; color: #3c5aa0; opacity: 0.07; }

	.cd-attach { border: 0.8pt dashed #888; padding: 12pt; text-align: center; }
	.cd-attach-label { font-size: 8pt; color: #555; }
	.cd-attach-file { font-weight: 700; margin-top: 4pt; }

	.cd-page-break { page-break-before: always; }
	.cd-body { position: relative; z-index: 1; }
</style>

<div id="header-html">
	{#
		Fixed height, deliberately. The framework measures this band and sizes the
		header page to whatever comes back, so a band whose height depends on its
		content produces a page that sometimes cannot hold it -- and the row then
		moves to a second sheet that is never merged. Pinning the height makes the
		measurement constant across every document; content that would exceed it is
		clipped, which is visible and fixable, rather than silently dropping the
		entire control block.
	#}
	<div class="cd-headband">{{ control_header(doc) }}</div>
</div>

<div id="footer-html">
	<table class="cd-footer">
		<tr>
			<td class="cd-notice">
				Notice: this document is proprietary and its contents are the exclusive property of
				Hatim Carbon Co. Pvt. Ltd. It may not be reproduced in any form without prior
				written permission.
			</td>
			<td class="cd-pageno">
				{{ doc.name }} &nbsp;&middot;&nbsp; Issue {{ doc.issue_number or "-" }} / Rev {{ doc.revision_number or "-" }}
			</td>
		</tr>
	</table>
</div>

{{ watermark(doc) }}

<div class="cd-body">
	{{ title_block(doc) }}
	{{ body(doc) }}
	{{ authority_block(doc) }}
	{{ change_history(doc) }}
</div>
